from pathlib import Path
import json

lab = json.loads(
    Path("assets/datasets/movielens/factor_lab.json").read_text(encoding="utf-8")
)

for method, scope in lab["scorecards"].items():
    print(method, scope["warm"])
for method, metrics in lab["report"]["rating_metrics"].items():
    print(method, metrics)
assert lab["report"]["rating_metrics"]["explicit_als"]["warm_known_count"] == 1311
